            "Título da publicação": "Na Parte I, apresentamos o Complexo Fotovoltaico Bom Jardim: 188,95 MW, 378.108 módulos, quatro frentes de fiscalização técnica em campo.\n\nHoje, os números que não aparecem nos releases de inauguração.\n\nToda obra de grande porte gera um volume massivo de informação técnica: registros fotográficos, relatórios de inspeção, ocorrências, controle de credenciamento e documentação de conformidade.\n\nNa maioria dos projetos, esse acervo fica disperso — e-mails, planilhas, grupos de mensagem, dificultando a rastreabilidade. No Complexo Bom Jardim, foi diferente.\n\nA INOVA utilizou o Nextek© Manager — nossa plataforma de gerenciamento e fiscalização de obras — para centralizar toda a operação técnica do projeto em um único ambiente.\n\nOs números do projeto registrados na plataforma:\n📸 97.499 registros fotográficos indexados por frente de obra e data, sendo gerados 597 diários de obra\n📋 6.847 relatórios checklists de inspeção gerados e assinados digitalmente, tendo sido inspecionados 61.574 itens\n⚠️ 457 ocorrências registradas, tratadas e com evidência documentada\n\nCada número representa uma decisão documentada.\n\nUma evidência técnica disponível para o dono do ativo — a qualquer momento, mesmo anos após a entrega.\n\nRastreabilidade não é burocracia. É o que garante que o proprietário saiba, de fato, o que foi construído e como.\n\nConheça o Nextek© Manager 👉 nextekmanager.com.br\n\n#NektekManager #GerenciamentoDeObras #FiscalizaçãoTécnica #EnergiaSolar #OwnerEngineer",
            "Link da publicação": "https://www.linkedin.com/feed/update/urn:li:activity:7455609296664543232",
